import ij.IJ;import ij.ImagePlus;import java.nio.file.*;import java.security.*;import java.util.*;
public class ReviewGangliaMasks {
 static String hash(byte[] a)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(a))s.append(String.format("%02x",b&255));return s.toString();}
 public static void main(String[] args)throws Exception{System.out.print("{");for(int i=0;i<args.length;i++){Path f=Path.of(args[i]);ImagePlus im=IJ.openImage(f.toString());if(im==null||im.getWidth()!=1024||im.getHeight()!=1024||im.getStackSize()!=1||im.getBitDepth()!=8)throw new AssertionError("geometry/type");byte[] p=(byte[])im.getProcessor().getPixels();int fg=0;for(byte b:p){if(b!=0&&b!=(byte)255)throw new AssertionError("nonbinary");if(b!=0)fg++;}if(i>0)System.out.print(",");System.out.print("\""+f.getFileName()+"\":{\"width\":1024,\"height\":1024,\"bit_depth\":8,\"slices\":1,\"foreground_pixels\":"+fg+",\"pixel_width\":"+im.getCalibration().pixelWidth+",\"pixel_height\":"+im.getCalibration().pixelHeight+",\"unit\":\""+im.getCalibration().getUnit()+"\",\"mask_pixels_uint8_row_major_sha256\":\""+hash(p)+"\",\"mask_tiff_sha256\":\""+hash(Files.readAllBytes(f))+"\"}");im.close();}System.out.println("}");}
}
